#include<bits/stdc++.h>

using namespace std;

const int N = 3010;

vector<pair<int, int>> g[N];
int p[N];
int pe[N];
int used[N];
int n, m;
vector<int> bad_edges;
int cycle[N];
int xs[N], ys[N];

void dfs1(int x)
{
for(auto [y, i] : g[x])
if(p[y] == -1)
{
p[y] = x;
pe[y] = i;
dfs1(y);
}
else if(p[x] != y)
bad_edges.push_back(i);
}

void go_to_root(int x)
{
while(x != 0)
{
cycle[pe[x]] ^= 1;
x = p[x];
}
}

void dfs2(int x)
{
used[x] = true;
for(auto [y, i] : g[x])
if(cycle[i] == 0 && !used[y])
dfs2(y);
}

void solve()
{
cin >> n >> m;
bad_edges.clear();
for(int i = 0; i < n; i++)
{
g[i].clear();
p[i] = -1;
pe[i] = -1;
}
for(int i = 0; i < m; i++)
{
int x, y;
cin >> x >> y;
--x;
--y;
xs[i] = x;
ys[i] = y;
g[x].push_back(make_pair(y, i));
g[y].push_back(make_pair(x, i));
}

p[0] = 0;
dfs1(0);
sort(bad_edges.begin(), bad_edges.end());
bad_edges.erase(unique(bad_edges.begin(), bad_edges.end()), bad_edges.end());

int k = bad_edges.size();
for(int mask = 1; mask < (1 << k); mask++)
{
for(int edge = 0; edge < m; edge++) cycle[edge] = 0;
for(int bit = 0; bit < k; bit++)
if((mask >> bit) & 1)
{
go_to_root(xs[bad_edges[bit]]);
go_to_root(ys[bad_edges[bit]]);
cycle[bad_edges[bit]] ^= 1;
}
for(int vertex = 0; vertex < n; vertex++)
used[vertex] = 0;
dfs2(0);
bool good = true;
for(int vertex = 0; vertex < n; vertex++)
if(!used[vertex])
good = false;
if(good)
{
cout << "YES\n";
return;
}
}
cout << "NO\n";
}

int main()
{
ios_base::sync_with_stdio(0);
cin.tie(0);
int t;
cin >> t;
for(int i = 0; i < t; i++)
solve();
}

